# Generated by ctf init; paths are passed as data, never evaluated.
ctf() {
    case ${1-} in
        new|go|use) ;;
        *) command ctf "$@"; return $? ;;
    esac
    local ctf_file ctf_status ctf_dest
    ctf_file=$(mktemp "${TMPDIR:-/tmp}/ctf-cd.XXXXXXXX") || return 1
    if CTF_CD_FILE="$ctf_file" command ctf "$@"; then
        ctf_status=0
    else
        ctf_status=$?
    fi
    if [ "$ctf_status" -eq 0 ] && [ -s "$ctf_file" ]; then
        if IFS= read -r -d '' ctf_dest < "$ctf_file"; then
            builtin cd -- "$ctf_dest" || ctf_status=$?
        else
            printf '%s\n' 'ctf: invalid directory handoff' >&2
            ctf_status=1
        fi
    fi
    rm -f -- "$ctf_file"
    return "$ctf_status"
}
